#include "../../storage/TracyDiskIndex64.hpp"
#include "../../storage/TracyMappedHashIndex64.hpp"
#include "../../storage/TracyCatalogBatchDirectory.hpp"
#include "../../storage/TracyResourceIntervals.hpp"
#include "../../analysis/TracyPagedRecordStore.hpp"
#include <chrono>
#include <algorithm>
#include <cstdlib>
#include <cstdio>
#include <string_view>
#include <vector>
using Clock=std::chrono::steady_clock;
static double Seconds(Clock::time_point start){return std::chrono::duration<double>(Clock::now()-start).count();}
static uint64_t Number(const char* value){char* end=nullptr;const auto n=std::strtoull(value,&end,10);if(!end||*end||!n)throw std::runtime_error("benchmark_argument");return n;}
int main(int argc,char** argv){try{
 if(argc<4)return 2;const std::string_view mode=argv[1];const auto root=std::filesystem::path(argv[2]);std::filesystem::create_directories(root);
 tracy::storage::ResourceLimits limits;limits.streamBytes=16ull<<30;limits.diskReserveBytes=0;limits.maximumPrivateBytes=20ull<<30;tracy::storage::ResourceSample sample;sample.physicalTotal=64ull<<30;sample.physicalAvailable=48ull<<30;sample.systemCommitLimit=64ull<<30;
 tracy::storage::ConversionResources resources(limits,[&]{return sample;},[]{return 1ull<<40;});
 if(mode=="disk-index"){
   const auto count=Number(argv[3]);auto started=Clock::now();tracy::storage::DiskIndex64 index(root/"index.bin",std::string(64,'a'),resources);
   for(uint64_t i=0;i<count;++i)index.Upsert((i+1)*11400714819323198485ull,i);const auto build=Seconds(started);started=Clock::now();index.Seal();const auto seal=Seconds(started);started=Clock::now();uint64_t checksum=0;const auto queries=std::min<uint64_t>(count,65536);for(uint64_t i=0;i<queries;++i)checksum+=*index.Find((i+1)*11400714819323198485ull);const auto query=Seconds(started);const auto s=index.Statistics();
   std::printf("{\"mode\":\"disk-index\",\"count\":%llu,\"build_seconds\":%.9f,\"seal_seconds\":%.9f,\"query_seconds\":%.9f,\"queries\":%llu,\"checksum\":%llu,\"page_loads\":%llu,\"page_writes\":%llu,\"evictions\":%llu,\"eviction_candidates\":%llu,\"parent_updates\":%llu,\"disk_peak\":%llu,\"workspace_peak\":%llu}\n",(unsigned long long)count,build,seal,query,(unsigned long long)queries,(unsigned long long)checksum,(unsigned long long)s.pageLoads,(unsigned long long)s.pageWrites,(unsigned long long)s.evictions,(unsigned long long)s.evictionCandidates,(unsigned long long)s.parentUpdates,(unsigned long long)resources.DiskPeak(),(unsigned long long)resources.Workspace()->Snapshot().peakBytes);
 }else if(mode=="mapped-hash"){
   const auto count=Number(argv[3]);auto started=Clock::now();tracy::storage::MappedHashIndex64 index(root/"index.bin",resources);
   for(uint64_t i=0;i<count;++i)index.Upsert((i+1)*11400714819323198485ull,i);const auto build=Seconds(started);started=Clock::now();const auto sealStats=index.Seal();const auto seal=Seconds(started);started=Clock::now();uint64_t checksum=0;const auto queries=std::min<uint64_t>(count,65536);for(uint64_t i=0;i<queries;++i)checksum+=*index.Find((i+1)*11400714819323198485ull);const auto query=Seconds(started);
   std::printf("{\"mode\":\"mapped-hash\",\"count\":%llu,\"build_seconds\":%.9f,\"seal_seconds\":%.9f,\"digest_seconds\":%.9f,\"flush_seconds\":%.9f,\"digest_bytes\":%llu,\"hash_backend\":\"%s\",\"query_seconds\":%.9f,\"queries\":%llu,\"checksum\":%llu,\"disk_current\":%llu,\"disk_peak\":%llu,\"workspace_peak\":%llu}\n",(unsigned long long)count,build,seal,double(sealStats.digestNanoseconds)/1e9,double(sealStats.flushNanoseconds)/1e9,(unsigned long long)sealStats.digestBytes,tracy::analysis::Sha256Backend(),query,(unsigned long long)queries,(unsigned long long)checksum,(unsigned long long)resources.DiskCurrent(),(unsigned long long)resources.DiskPeak(),(unsigned long long)resources.Workspace()->Snapshot().peakBytes);
 }else if(mode=="directory"){
   if(argc!=5)return 2;const auto generations=Number(argv[3]),batches=Number(argv[4]);auto started=Clock::now();tracy::storage::CatalogBatchDirectory directory(root/"directory",std::string(64,'b'),resources);for(uint64_t g=0;g<generations;++g)directory.AddGeneration((g+1)*1000003);for(uint64_t b=0;b<batches;++b)directory.AddBatch(b,(b%generations+1)*1000003,uint8_t(b%10));directory.Seal();const auto build=Seconds(started);started=Clock::now();uint64_t checksum=0,visited=0;for(uint64_t g=0;g<generations;++g)for(uint8_t kind=0;kind<10;++kind)visited+=directory.Visit((g+1)*1000003,kind,[&](uint64_t batch){checksum+=batch;});const auto visit=Seconds(started);const auto s=directory.Statistics();
   std::printf("{\"mode\":\"directory\",\"generations\":%llu,\"batches\":%llu,\"build_seconds\":%.9f,\"visit_seconds\":%.9f,\"visited\":%llu,\"checksum\":%llu,\"logical_bytes\":%llu,\"disk_peak\":%llu,\"workspace_peak\":%llu}\n",(unsigned long long)generations,(unsigned long long)batches,build,visit,(unsigned long long)visited,(unsigned long long)checksum,(unsigned long long)s.logicalBytes,(unsigned long long)resources.DiskPeak(),(unsigned long long)resources.Workspace()->Snapshot().peakBytes);
 }else if(mode=="intervals"){
   if(argc!=5)return 2;const auto history=Number(argv[3]),queries=Number(argv[4]);auto started=Clock::now();tracy::storage::ResourceIntervals intervals(root/"intervals",resources,std::string(64,'c'));tracy::JnGpuCatalogResourceRecordV1 row{};row.pointerToken=777;
   for(uint64_t i=0;i<history;++i){row.resourceId=i+1;row.time=int64_t(i*3);row.operation=uint8_t(tracy::JnGpuCatalogRecordOperation::Create);intervals.Add(row);row.time=int64_t(i*3+1);row.operation=uint8_t(tracy::JnGpuCatalogRecordOperation::Destroy);intervals.Add(row);}intervals.Seal();const auto build=Seconds(started);started=Clock::now();uint64_t checksum=0;for(uint64_t i=0;i<queries;++i)checksum+=intervals.Resolve(777,int64_t((i%history)*3));const auto query=Seconds(started);const auto s=intervals.Statistics();
   std::printf("{\"mode\":\"intervals\",\"history\":%llu,\"queries\":%llu,\"build_seconds\":%.9f,\"query_seconds\":%.9f,\"checksum\":%llu,\"node_visits\":%llu,\"max_nodes_per_resolve\":%llu,\"disk_peak\":%llu,\"workspace_peak\":%llu}\n",(unsigned long long)history,(unsigned long long)queries,build,query,(unsigned long long)checksum,(unsigned long long)s.intervalNodeVisits,(unsigned long long)s.maxNodesPerResolve,(unsigned long long)resources.DiskPeak(),(unsigned long long)resources.Workspace()->Snapshot().peakBytes);
 }else if(mode=="paged"){
   const auto bytes=Number(argv[3]);if(bytes%sizeof(uint64_t))throw std::runtime_error("benchmark_paged_size");tracy::analysis::PagedRecordOptions options;options.blockBytes=4*1024*1024;options.workspace=resources.Workspace();options.beforeMemoryAllocation=[&](uint64_t n){resources.Check(n);};options.beforeFileGrowth=[&](const auto& p,uint64_t n){resources.BeforeFileGrowth(p,n);};options.renameFile=[&](const auto& a,const auto& b){resources.RenameOwned(a,b);};std::vector<uint64_t> chunk((1ull<<20)/sizeof(uint64_t));uint64_t next=0;auto started=Clock::now();{tracy::analysis::PagedRecordWriter writer(root/"records",std::string(64,'d'),sizeof(uint64_t),options);while(next<bytes/8){const auto count=std::min<uint64_t>(chunk.size(),bytes/8-next);for(uint64_t i=0;i<count;++i)chunk[i]=next+i;writer.Append(chunk.data(),count);next+=count;}writer.Commit();}const auto build=Seconds(started);started=Clock::now();uint64_t expected=0,checksum=0;tracy::analysis::PagedRecordReader reader(root/"records",std::string(64,'d'),sizeof(uint64_t),options);const auto s=reader.VisitValidated([&](const void* p,uint64_t n){const auto* rows=static_cast<const uint64_t*>(p);for(uint64_t i=0;i<n;++i){if(rows[i]!=expected++)throw std::runtime_error("benchmark_paged_order");checksum+=rows[i];}});const auto visit=Seconds(started);
   std::printf("{\"mode\":\"paged\",\"bytes\":%llu,\"build_seconds\":%.9f,\"visit_seconds\":%.9f,\"blocks\":%llu,\"records\":%llu,\"decoded_bytes\":%llu,\"stored_bytes\":%llu,\"checksum\":%llu,\"disk_peak\":%llu,\"workspace_peak\":%llu}\n",(unsigned long long)bytes,build,visit,(unsigned long long)s.blocks,(unsigned long long)s.records,(unsigned long long)s.decodedBytes,(unsigned long long)s.storedBytes,(unsigned long long)checksum,(unsigned long long)resources.DiskPeak(),(unsigned long long)resources.Workspace()->Snapshot().peakBytes);
 }else return 2;return 0;
 }catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}}
